(()=>{"use strict";self.addEventListener("push",t=>{if(t.data)try{let i=t.data.json(),e={body:i.body,icon:"/icon.png",badge:"/icon.png",vibrate:[100,50,100],data:{url:i.url||"https://schedule.triddle.dev"}};t.waitUntil(self.registration.showNotification(i.title,e))}catch(t){console.error("Push event data is not valid JSON:",t)}}),self.addEventListener("notificationclick",t=>{t.notification.close();let i=t.notification.data?.url||"https://schedule.triddle.dev";t.waitUntil(self.clients.openWindow(i))})})();